mapper.select:
/*selectBuyerMpSoOrderProgressList*/
SELECT (ROWNUM ) No, --[00] No S.PR_NO , --[01] 요청번호 S.REF_PR_NO , --[02] 관리번호 S.BUYER_ITEM_NO , --[03] 상품코드 S.CHANGE_DATE , --[04] 주문일 S.ADD_DATE , --[04] 주문일 ADD_DATE S.DESCRIPTION , --[05] 상품명 S.SPECIFICATION , --[06] 규격 S.UNIT_PRICE , --[07] 단가 S.ITEM_AMT , --[08] 금액 S.RD_DATE , --[09] 배송희망일 S.CD_DATE , --[10] 배송확정일 S.UNIT_MEASURE , --[11] 단위 S.RETURN_REASON_IMG , --[12] 사유 S.PO_CREATE_DATE , --[13] 발주일 S.ITEM_QTY , --[14] 발주수량 S.AGENT_TEXT, --[15] 공급사명 S.PO_NO , --[16] 발주번호 S.STATUS_TEXT , --[17] 배송상태 S.GR_QTY , --[18] 입고수량 S.DI_QTY, --[19] DI_QTY 배송확정수량 S.BUYER, --[20] BUYER 구매사코드 S.PR_SEQ, --[21] PR_SEQ 주문항번 S.PO_SEQ, --[22] PO_SEQ 발주항번, S.AGENT_CODE, --[23] AGENT_CODE 공급사코드 S.TARGET_QTY, --[24] TARGET_QTY S.BYIT_COMORG_CODE, --[25] BYIT_COMORG_CODE S.CONTRACT_NO, --[26] CONTRACT_NO S.CONTRACT_SEQ, --[27] CONTRACT_SEQ S.RETURN_REASON, --[28] RETURN_REASON S.RECV_FLAG, --[29] RECV_FLAG S.REF_NO, --[30] REF_NO S.CHANGE_TIME --[31] CHANGE_TIME , (SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE PRHD.BUYER = S.BUYER AND PRHD.PR_NO = S.PR_NO) CARD_USE_FLAG --[32] CARD_USE_FLAG 카드여부 , (SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE PRHD.BUYER = S.BUYER AND PRHD.PR_NO = S.PR_NO) CARD_CONFIRM_NO --[33] CARD_CONFIRM_NO 승인번호 , NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = s.BUYER AND TYPE = 'C001' AND CODE = s.BUDGET_DEPT),(SELECT LTEXT FROM COWAY_BUDGET_ORG_ET_TREE WHERE BGORG = s.BUDGET_DEPT AND ROWNUM = 1)) AS BUDGET_DEPT_NAME -- 예산부서명 , NVL((SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = s.BUYER AND TYPE = 'Z014' AND CODE = s.ACCOUNT_TYPE),(SELECT LTEXT FROM COWAY_ACCOUNT_ET_OUTPUT WHERE BGACT = s.ACCOUNT_TYPE AND ROWNUM = 1)) AS ACCOUNT_TYPE_NAME -- 계정명 ,S.STATUS_CODE ,(SELECT TEXT5 FROM ICOMCOD1 WHERE TYPE = 'C016' AND CODE = S.STATUS_CODE) STATUS_BACK_CODE ,S.PROCESS_TYPE ,NVL(S.RE_WMRE_NO,'Y') RE_PO ,S.RE_PROCESS_TYPE ,CASE WHEN S.RE_WMRE_TYPE = '01' THEN '반품 요청' WHEN S.RE_WMRE_TYPE = '02' THEN '교환 요청' WHEN S.RE_WMRE_TYPE = '09' THEN '주문취소 요청' ELSE '' END RE_WMRE_TYP ,S.LEGACY_PO_NO ,S.DOOS_ITEM_NO ,S.ADD_USER_NAME ,S.DLVY_DATE ,S.SIZE_QTY ,S.SIZE_LEN ,S.REQ_USER_NAME ,S.GW_NO ,(SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = 'KRKORE0001' AND TYPE = 'SBIM' AND CODE1 = S.BYIT_COMORG_CODE AND CODE2 = S.BUYER_ITEM_NO AND FLAG = 'Y') AS ITEM_NO_MNG_FLAG ,(SELECT TEXT2 FROM ICOMCOD3 WHERE BUYER = 'KRKORE0001' AND TYPE = 'SBIM' AND CODE1 = S.BYIT_COMORG_CODE AND CODE2 = S.BUYER_ITEM_NO AND FLAG = 'Y') AS NAMECARD_RPT ,S.REMARK ,S.PARCEL_COM_CODE ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = S.PARCEL_COM_CODE) AS PARCEL_COM_NAME ,S.PARCEL_INV_NO ,REPLACE(INV_NO_URL,'param',PARCEL_INV_NO) AS REAL_INV_NO_URL ,S.PURCHASER_NAME --발주자 추가 ,S.PURCHASER_DEPT --발주부서 추가 ,S.REQ_USER_DEPT --요청부서 추가 ,S.DELY_TO_LOCATION_TEXT ,S.PO_REMARK ,S.DELY_TO_LOCATION ,S.MAKER_NAME --제조사명 추가 ,S.REQ_USER_INFO ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C021' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 1) AND FLAG = 'Y') AS HLC_REF_PR_NO0 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 2) AND FLAG = 'Y') AS HLC_REF_PR_NO1 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C020' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 3) AND FLAG = 'Y') AS HLC_REF_PR_NO2 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 4)) AS HLC_REF_PR_NO3 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C022' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 5) AND FLAG = 'Y') AS HLC_REF_PR_NO4
-- 엑셀다운로드 양식을 변경하는 고객사 대응 (한샘)
,F_SPLIT(S.REF_PR_NO, '^', 1) AS REF_PR_NO0 ,F_SPLIT(S.REF_PR_NO, '^', 2) AS REF_PR_NO1 ,F_SPLIT(S.REF_PR_NO, '^', 3) AS REF_PR_NO2 ,F_SPLIT(S.REF_PR_NO, '^', 4) AS REF_PR_NO3 ,(SELECT DEPARTMENT FROM ICOMLUSR i WHERE legacy_user_id = F_SPLIT(S.REF_PR_NO, '^', 1) AND com_code = S.BUYER) AS REF_PR_NO4-- 실사용자 코스트센터(부서코드) ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = S.BUYER AND FLAG = 'Y' AND CODE = (SELECT DEPARTMENT FROM ICOMLUSR i WHERE LEGACY_USER_ID = F_SPLIT(S.REF_PR_NO, '^', 1) AND COM_CODE = S.BUYER AND STATUS <> 'D')) AS REF_PR_NO5-- 실사용자 코스트센터명(부서명) -- 입고일 ,(SELECT MAX(GR_DATE) FROM ICOMGRDT WHERE BUYER = S.BUYER AND PO_NO = S.PO_NO AND PO_SEQ = S.PO_SEQ AND STATUS <> 'D') AS GR_DATE
-- 엑셀다운로드 양식을 변경하는 고객사 대응 (깨끗한나라)
,F_SPLIT(S.REF_PR_NO, '^', 1) AS REF_PR_NO0 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 1)) AS REF_PR_NO1 ,F_SPLIT(S.REF_PR_NO, '^', 2) AS REF_PR_NO2 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C020' AND COMPANY_CODE = S.BUYER AND CODE = F_SPLIT(S.REF_PR_NO, '^', 2)) AS REF_PR_NO3
FROM ( SELECT ROWNUM NUM, A.PR_NO, A.REF_PR_NO, A.BUYER_ITEM_NO, A.CHANGE_DATE, A.ADD_DATE, A.DESCRIPTION, A.SPECIFICATION, A.UNIT_PRICE, A.ITEM_AMT, A.RD_DATE, A.CD_DATE, A.UNIT_MEASURE, A.RETURN_REASON_IMG, A.PO_CREATE_DATE, A.ITEM_QTY, A.AGENT_TEXT, A.PO_NO, A.STATUS_TEXT, A.GR_QTY, A.DI_QTY, A.BUYER, A.PR_SEQ, A.PO_SEQ, A.AGENT_CODE, A.TARGET_QTY, A.BYIT_COMORG_CODE, A.CONTRACT_NO, A.CONTRACT_SEQ, A.RETURN_REASON, A.RECV_FLAG, A.REF_NO, A.CHANGE_TIME,
A.BUDGET_DEPT BUDGET_DEPT, A.ACCOUNT_TYPE ACCOUNT_TYPE, A.STATUS_CODE, A.PROCESS_TYPE ,F_SPLIT(A.WMRE_INFO,'@@^^',1) RE_WMRE_NO ,F_SPLIT(A.WMRE_INFO,'@@^^',2) RE_PROCESS_TYPE ,F_SPLIT(A.WMRE_INFO,'@@^^',3) RE_WMRE_TYPE ,A.LEGACY_PO_NO ,A.DOOS_ITEM_NO ,A.ADD_USER_NAME ,A.DLVY_DATE ,A.SIZE_QTY ,A.SIZE_LEN ,A.REQ_USER_NAME ,A.GW_NO ,A.REMARK ,A.PARCEL_COM_CODE ,A.PARCEL_INV_NO ,(SELECT TEXT5 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = A.PARCEL_COM_CODE) AS INV_NO_URL ,A.PURCHASER_NAME --발주자 추가 ,A.PURCHASER_DEPT --발주부서 추가 ,A.REQ_USER_DEPT --요청부서 추가 ,A.DELY_TO_LOCATION_TEXT ,A.PO_REMARK ,A.DELY_TO_LOCATION ,A.MAKER_NAME --제조사명 추가 ,A.REQ_USER_INFO FROM ( SELECT PR.PR_NO PR_NO,
CASE WHEN PR.BUYER ='KRKOLO0018' THEN NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE ='M014' AND CODE = PR.REF_PR_NO),PR.REF_PR_NO) ELSE PR.REF_PR_NO END AS REF_PR_NO,
TRIM(PR.BUYER_ITEM_NO) BUYER_ITEM_NO, PR.CHANGE_DATE CHANGE_DATE, PR.ADD_DATE ADD_DATE, PR.DESCRIPTION DESCRIPTION, PR.SPECIFICATION SPECIFICATION, NVL(PO.UNIT_PRICE, PR.TARGET_PRICE) UNIT_PRICE, NVL(PO.UNIT_PRICE, PR.TARGET_PRICE) * DECODE(PO.ITEM_QTY,NULL,PR.TARGET_QTY,PO.ITEM_QTY) ITEM_AMT, PR.RD_DATE RD_DATE, NVL( (SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND STATUS != 'D'), NVL( (SELECT MAX(BUYER_DS_DATE) FROM ICOMPORS WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND DS_DATE = PO.DS_DATE AND STATUS != 'D'), F_GET_WORKINGDAY(PO.ADD_DATE, (SELECT MAX(DELIVERY_LT) FROM ICOMCQDT WHERE BUYER = PR.BYIT_COMORG_CODE AND CONTRACT_NO = PR.CONTRACT_NO AND CONTRACT_SEQ = PR.CONTRACT_SEQ)) ) ) AS CD_DATE, CASE WHEN PO.PROCESS_TYPE = '0' THEN ( SELECT MAX(IVDT.DELIVERY_DATE) FROM ICOMIVDT IVDT WHERE IVDT.BUYER = PO.BUYER AND IVDT.PO_NO = PO.PO_NO AND IVDT.PO_SEQ = PO.PO_SEQ AND IVDT.STATUS != 'D' ) ELSE ( SELECT MAX(WMDT.DELIVERY_DATE) FROM WMSIVDT WMDT WHERE WMDT.BUYER = PO.BUYER AND WMDT.PO_NO = PO.PO_NO AND WMDT.PO_SEQ = PO.PO_SEQ AND WMDT.STATUS != 'D' ) END AS DLVY_DATE , PR.UNIT_MEASURE UNIT_MEASURE, DECODE(NVL(TRIM(PR.RETURN_REASON),''),'','/resources/images/icon2.gif','/resources/images/icon.gif') RETURN_REASON_IMG, (SELECT PO_CREATE_DATE FROM ICOMPOHD PH WHERE PO.PO_NO = PH.PO_NO AND PO.BUYER = PH.BUYER AND PH.STATUS <> 'D') PO_CREATE_DATE, NVL(PO.ITEM_QTY,0) ITEM_QTY, DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', '코리아이플랫폼(주)', (SELECT A.COM_NAME_LOC FROM ICOMCMPY A, ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO AND A.COM_CODE = B.AGENT)) AGENT_TEXT, PO.PO_NO PO_NO,
F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 1) STATUS_TEXT, F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) STATUS_CODE,
NVL(PO.GR_QTY,0) GR_QTY, PO.DI_QTY DI_QTY, PR.BUYER BUYER, PR.PR_SEQ PR_SEQ, PO.PO_SEQ PO_SEQ, DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', 'KRKORE0001', (SELECT B.AGENT FROM ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO)) AGENT_CODE, PR.TARGET_QTY TARGET_QTY, PR.BYIT_COMORG_CODE BYIT_COMORG_CODE, PR.CONTRACT_NO CONTRACT_NO, PR.CONTRACT_SEQ CONTRACT_SEQ, DECODE(NVL(TRIM(PR.RETURN_REASON),''),'','ALL',TRIM(PR.RETURN_REASON)) RETURN_REASON, PR.RECV_FLAG RECV_FLAG, PR.REF_NO REF_NO, SUBSTR(PR.CHANGE_TIME,0,2)||':'||SUBSTR(PR.CHANGE_TIME,3,2)||':'||SUBSTR(PR.CHANGE_TIME,5,2) CHANGE_TIME,
PR.BUDGET_DEPT BUDGET_DEPT, PR.ACCOUNT_TYPE ACCOUNT_TYPE, PO.PROCESS_TYPE ,(SELECT MAX(WMRE.WMRE_NO||'@@^^'||WMRE.PROCESS_TYPE||'@@^^'||WMRE.WMRE_TYPE) FROM BNTWMRE WMRE WHERE WMRE.BUYER = PO.BUYER AND WMRE.PO_NO = PO.PO_NO AND WMRE.PO_SEQ = PO.PO_SEQ AND WMRE.FLAG NOT IN ('13','19')) AS WMRE_INFO ,PR.LEGACY_PO_NO ,(SELECT MAX(ITEM_NO) FROM ICOMCQDT WHERE BUYER = PO.BUYER AND PO.BUYER_ITEM_NO = BUYER_ITEM_NO) AS DOOS_ITEM_NO , PR.ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS REQ_USER_NAME , (SELECT MAX(TARGET) FROM ICOMTRGW WHERE COM_CODE = PR.BUYER AND DOC_NAME = 'PR' AND KEY_1 = PR.PR_NO) AS GW_NO , PR.REMARK , CASE WHEN PO.PROCESS_TYPE = '0' THEN ( SELECT MAX(IVHD.PARCEL_COM_CODE) FROM ICOMIVHD IVHD, ICOMIVDT IVDT WHERE IVDT.BUYER = PO.BUYER AND IVDT.PO_NO = PO.PO_NO AND IVDT.PO_SEQ = PO.PO_SEQ AND IVDT.STATUS != 'D' AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO = IVHD.INV_NO AND IVHD.STATUS != 'D') ELSE ( SELECT MAX(WMDT.DELIVERY_COMPANY) FROM WMSIVDT WMDT WHERE WMDT.BUYER = PO.BUYER AND WMDT.PO_NO = PO.PO_NO AND WMDT.PO_SEQ = PO.PO_SEQ AND WMDT.STATUS != 'D' ) END AS PARCEL_COM_CODE , CASE WHEN PO.PROCESS_TYPE = '0' THEN ( SELECT MAX(IVHD.PARCEL_INV_NO) FROM ICOMIVHD IVHD, ICOMIVDT IVDT WHERE IVDT.BUYER = PO.BUYER AND IVDT.PO_NO = PO.PO_NO AND IVDT.PO_SEQ = PO.PO_SEQ AND IVDT.STATUS != 'D' AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO = IVHD.INV_NO AND IVHD.STATUS != 'D') ELSE ( SELECT MAX(WMDT.DELIVERY_NO) FROM WMSIVDT WMDT WHERE WMDT.BUYER = PO.BUYER AND WMDT.PO_NO = PO.PO_NO AND WMDT.PO_SEQ = PO.PO_SEQ AND WMDT.STATUS != 'D' ) END AS PARCEL_INV_NO ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PR.PURCHASER_ID) AS PURCHASER_NAME --발주자 추가 ,(SELECT COD.TEXT2 FROM ICOMCOD2 COD WHERE COD.COMPANY_CODE=PR.BUYER AND COD.TYPE='C001' AND COD.CODE=PR.PURCHASER_DEPT) AS PURCHASER_DEPT --발주부서 추가 ,(SELECT COD.TEXT2 FROM ICOMCOD2 COD WHERE COD.COMPANY_CODE=PR.BUYER AND COD.TYPE='C001' AND COD.CODE=PR.ADD_USER_DEPT) AS REQ_USER_DEPT --요청부서 추가 , PR.DELY_TO_LOCATION_TEXT ,PO.PO_REMARK ,(SELECT DELY_TO_LOCATION FROM ICOMPOHD WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO) AS DELY_TO_LOCATION ,NVL(PO.MAKER_NAME,PR.MAKER_NAME) AS MAKER_NAME ,PR.REQ_USER_INFO AS REQ_USER_INFO FROM ICOMPRDT PR, ICOMPODT PO WHERE PR.BUYER = #{st_buyer}
AND PR.CHANGE_USER_ID = #{st_userid}
AND PR.CHANGE_USER_ID = #{st_userid}
AND PR.ADD_USER_DEPT = #{st_userDept}
AND PR.ADD_USER_DEPT = #{st_p060000114_search}
AND PR.CHANGE_USER_ID = #{st_userid}
AND PR.BUYER = PO.BUYER(+) AND PR.PR_NO = PO.PR_NO(+) AND PR.PR_SEQ = PO.PR_SEQ(+) AND PR.STATUS != 'D' AND PO.STATUS(+) != 'D' AND PR.ADD_DATE BETWEEN #{fromDate} AND #{toDate}
AND PR.PR_NO like '%'||UPPER( #{st_pr_no} ) ||'%'
AND UPPER(PR.LEGACY_PO_NO) like '%'||UPPER( #{st_legacy_po_no} ) ||'%'
AND PO.PO_NO like '%'||UPPER( #{st_po_no} ) ||'%'
AND PR.REF_PR_NO like '%'||UPPER( #{st_ref_no} ) ||'%'
AND UPPER(PR.BUYER_ITEM_NO) like '%'||UPPER(#{st_search_no}) ||'%'
AND PR.DESCRIPTION like '%'||#{st_search_no} ||'%'
AND PR.SPECIFICATION like '%'||#{st_search_no} ||'%'
AND PR.PR_NO like '%'||UPPER( #{st_search_no} ) ||'%'
AND PO.PO_NO like '%'||UPPER( #{st_search_no} ) ||'%'
AND PR.REF_PR_NO like UPPER( #{st_search_no} ) ||'%'
AND UPPER(PR.LEGACY_PO_NO) like UPPER( #{st_search_no} ) ||'%'
AND F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) = #{st_status}
AND PR.REQ_USER_ID = #{st_pur_user_id}
AND PR.PURCHASER_ID = #{st_pur_user_id}
AND PR.REQ_DEPT = #{st_pur_dept_code}
AND PR.PURCHASER_DEPT = #{st_pur_dept_code}
AND PR.PURCHASER_ID = #{st_pur_user_id}
AND PR.PURCHASER_DEPT = #{st_pur_dept_code}
ORDER BY PR.ADD_DATE DESC,PR.CHANGE_DATE DESC, PR.PR_NO DESC, PR.DESCRIPTION ${st_sortType} , PR.BUYER_ITEM_NO DESC )A )S

/*getBuyerMpSoGroupPurchaseOrderProgressList2*/ SELECT A.REF_PR_NO AS ADD_USER_ID ,(SELECT USR.LEGACY_USER_ID FROM ICOMLUSR USR WHERE USR.USER_ID = A.REF_PR_NO) AS ADD_LEGACY_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.REF_PR_NO) AS ADD_USER_NAME ,(SELECT NVL(TEXT1, DEPARTMENT) FROM ICOMCOD2, ICOMLUSR lusr WHERE COMPANY_CODE = A.BUYER AND COMPANY_CODE = lusr.COM_CODE AND lusr.USER_ID = A.REF_PR_NO AND TYPE='C001' AND CODE = lusr.DEPARTMENT )AS DEPARTMENT_NAME , B.BUYER_ITEM_NO , B.DESCRIPTION_LOC AS DESCRIPTION , B.SPECIFICATION AS SPECIFICATION , NVL(A.CART_QTY,1) AS TARGET_QTY , NVL(C.TARGET_PRICE,0) AS UNIT_PRICE , NVL(A.CART_QTY,1) * NVL(C.TARGET_PRICE,0) ITEM_AMT , CASE WHEN TO_CHAR(SYSDATE -31,'YYYYMMDD') < TO_CHAR(A.CREATE_DATE,'YYYYMMDD') THEN 'Y' ELSE 'N' END CHK_YN , TO_CHAR(A.CREATE_DATE,'YYYYMMDD') AS ADD_DATE , (SELECT COD2.TEXT4 FROM ICOMCOD2 COD2, ICOMLUSR USR WHERE COD2.COMPANY_CODE = USR.COM_CODE AND COD2.CODE = USR.DEPARTMENT AND COD2.TYPE = 'C001' AND COD2.FLAG = 'Y' AND COD2.COMPANY_CODE = A.BUYER AND USR.USER_ID = A.REF_PR_NO ) DELY_TO_LOCATION_TEXT , ( SELECT PHONE_NUMBER FROM ICOMLUSR USR WHERE USER_ID = A.REF_PR_NO) AS PHONE_NUMBER , A.BUYER , A.CONTRACT_NO , A.CONTRACT_SEQ , A.SEQ , A.USER_ID AS COWAY_CART_ID FROM COWAY_CART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USE_FLAG = 'C' AND TO_CHAR(A.CREATE_DATE,'YYYYMMDD') BETWEEN #{fromDate} AND #{toDate}
AND A.USER_ID = #{st_user_id}
AND B.BUYER_ITEM_NO LIKE '%'||#{st_search_no} ||'%'
AND B.DESCRIPTION_LOC LIKE '%'||#{st_search_no} ||'%'
AND B.SPECIFICATION LIKE '%'||#{st_search_no} ||'%'
ORDER BY A.CREATE_DATE, A.BUYER_ITEM_NO

/*getBuyerMpSoSellerRegProgressList*/ SELECT DECODE(A.USE_FLAG, 'O','요청','R','접수') AS USE_FLAG , B.BUYER_ITEM_NO , B.DESCRIPTION_LOC AS DESCRIPTION , B.SPECIFICATION AS SPECIFICATION , TO_CHAR(A.CREATE_DATE,'YYYYMMDD') AS ADD_DATE ,A.RD_DATE ,A.MG_NOTE , (SELECT USER_NAME_LOC FROM ICOMLUSR B WHERE B.USER_ID = F_SPLIT(A.MG_NOTE,',',1)) ||DECODE(F_SPLIT(A.MG_NOTE,',',2),NULL,'',' 외') AS REQ_USER_NM , A.IMAGE_KEY , A.BUYER , A.CONTRACT_NO , A.CONTRACT_SEQ , A.SEQ , A.USER_ID FROM COWAY_CART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USE_FLAG IN ('O','R') AND TO_CHAR(A.CREATE_DATE,'YYYYMMDD') BETWEEN #{fromDate} AND #{toDate}
AND A.USE_FLAG = #{st_use_status}
AND B.BUYER_ITEM_NO LIKE '%'||#{st_search_no} ||'%'
AND B.DESCRIPTION_LOC LIKE '%'||#{st_search_no} ||'%'
AND B.SPECIFICATION LIKE '%'||#{st_search_no} ||'%'
ORDER BY A.CREATE_DATE, A.BUYER_ITEM_NO

mapper.update:


 	/* setBuyerPrDtCancel */		 		
	UPDATE	ICOMPRDT
	SET		RECV_FLAG = 'GC',
			STATUS = 'R',
			CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
			RETURN_REASON = '본인 주문건 취소'
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PR_NO = #{st_pr_no}
	AND		PR_SEQ = #{st_pr_seq}



 	/* setBuyerPrHdCancel */		 		
	UPDATE	ICOMPRHD A
	SET		A.RECV_FLAG = DECODE((SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = A.BUYER AND PR_NO = A.PR_NO AND STATUS IN ('C','R') AND A.RECV_FLAG <> 'GC'), 0, 'GC', A.RECV_FLAG),
			A.STATUS = 'R',
			A.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			A.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PR_NO = #{st_pr_no}
